public async Task<List<PostSummary>> GetPostsByTitlePrefixAsync(
    BlogContext context,
    string prefix,
    CancellationToken cancellationToken)
{
    var matchingPosts =
        from post in context.Posts
        where post.Title.StartsWith(prefix)
        select new PostSummary(post.Id, post.Title);

